"""Puzzle Magnet Lab - rule model + BFS solver used to author levels.

Legend:
  #  wall            .  floor          (space) void
  H  hazard          P  pressure plate S  polarity switch
  G  gate            X  exit (player only; crates blocked)
  o  metal block     +  crate +        -  crate -
  1  player start +  2  player start -
"""
from collections import deque

DIRS = {'up': (0, -1), 'down': (0, 1), 'left': (-1, 0), 'right': (1, 0)}


class Level:
    def __init__(self, name, rows, hint=""):
        self.name = name
        self.rows = rows
        self.hint = hint
        self.h = len(rows)
        self.w = max(len(r) for r in rows)
        self.blocked = set()
        self.hazard = set()
        self.switch = set()
        self.plate = set()
        self.gate = set()
        self.exit = None
        self.start = None
        self.start_pol = 1
        self.crates = []
        for y, row in enumerate(rows):
            row = row.ljust(self.w)
            for x, ch in enumerate(row):
                c = (x, y)
                if ch == '#':
                    self.blocked.add(c)
                elif ch == ' ':
                    self.blocked.add(c)
                elif ch == 'o':
                    self.blocked.add(c)
                elif ch == 'H':
                    self.hazard.add(c)
                elif ch == 'S':
                    self.switch.add(c)
                elif ch == 'P':
                    self.plate.add(c)
                elif ch == 'G':
                    self.gate.add(c)
                elif ch == 'X':
                    self.exit = c
                elif ch in '12':
                    self.start = c
                    self.start_pol = 1 if ch == '1' else -1
                elif ch == '+':
                    self.crates.append((x, y, 1))
                elif ch == '-':
                    self.crates.append((x, y, -1))
        self.crates = tuple(sorted(self.crates))

    def initial(self):
        return (self.start, self.start_pol, self.crates)

    def powered(self, crates):
        if not self.plate:
            return True
        covered = set((x, y) for x, y, _ in crates)
        return self.plate.issubset(covered)

    def blocked_cell(self, cell, crates, powered):
        if cell in self.blocked:
            return True
        if cell in self.gate:
            return not powered
        if cell == self.exit:
            return True  # exit pad repels crates
        return False

    def moves(self, state):
        """yield (dir_name, new_state, events)"""
        (px, py), pol, crates = state
        crate_at = {}
        for c in crates:
            crate_at[(c[0], c[1])] = c
        for name, (dx, dy) in DIRS.items():
            t = (px + dx, py + dy)
            goals = self._step(state, (px, py), pol, t, (dx, dy), crate_at)
            if goals is None:
                yield name, None, {'invalid': True}
            else:
                yield name, goals[0], goals[1]

    def _step(self, state, ppos, pol, t, d, crate_at):
        pw = self.powered(state[2])
        events = {}
        if t in self.blocked or (t in self.gate and not pw):
            return None
        moved = []          # (crate, new_pos)
        destroyed = []
        if t in crate_at:
            c = crate_at[t]
            if c[2] != pol:
                return None  # opposite polarity: cannot push
            # push chain
            chain = [c]
            cur = t
            while True:
                nxt = (cur[0] + d[0], cur[1] + d[1])
                if nxt in crate_at:
                    nc = crate_at[nxt]
                    if nc[2] != pol:
                        return None
                    chain.append(nc)
                    cur = nxt
                    continue
                if self.blocked_cell(nxt, state[2], pw):
                    return None
                break
            events['push'] = True
            for c2 in reversed(chain):
                nxt = (c2[0] + d[0], c2[1] + d[1])
                if nxt in self.hazard:
                    destroyed.append(c2)
                else:
                    moved.append((c2, nxt))
        # player moves
        new_crates = dict(crate_at)
        for c2, np in moved:
            del new_crates[(c2[0], c2[1])]
        for c2 in destroyed:
            del new_crates[(c2[0], c2[1])]
        for c2, np in moved:
            new_crates[np] = (np[0], np[1], c2[2])
        # pull
        oldp = ppos
        b = (oldp[0] - d[0], oldp[1] - d[1])
        if b in new_crates:
            c = new_crates[b]
            if c[2] != pol:
                dest = oldp
                del new_crates[b]
                if dest in self.hazard:
                    destroyed.append(c)
                    events['pull_destroy'] = True
                else:
                    new_crates[dest] = (dest[0], dest[1], c[2])
                    events['pull'] = True
        if events.get('push'):
            events['push'] = True
        if destroyed:
            events['destroyed'] = [tuple(c) for c in destroyed]
        # flips
        flipped = []
        if oldp_new := None:
            pass
        if t in self.switch:
            flipped.append(('player', t))
        final = []
        for pos, c in new_crates.items():
            pol2 = c[2]
            if pos in self.switch and pos != (c[0], c[1]):
                pol2 = -pol2
                flipped.append((c, pos))
            final.append((pos[0], pos[1], pol2))
        if flipped:
            events['flip'] = flipped
        ns = (t, pol, tuple(sorted(final)))
        # player death
        if t in self.hazard:
            events['death'] = True
            return ns, events
        # power change
        pw2 = self.powered(ns[2])
        if pw2 != pw:
            events['power'] = pw2
        # win
        if t == self.exit and pw2:
            events['win'] = True
        return ns, events


def solve(level, max_nodes=900000):
    start = level.initial()
    seen = {start: None}
    q = deque([(start, 0)])
    nodes = 0
    if level.exit is None:
        return None, 0
    while q:
        state, depth = q.popleft()
        nodes += 1
        if nodes > max_nodes:
            return 'LIMIT', nodes
        for name, ns, ev in level.moves(state):
            if ns is None:
                continue
            if ev.get('death'):
                continue
            if ev.get('win'):
                seen[ns] = (state, name)
                # reconstruct
                path = [name]
                s = state
                while seen[s] is not None:
                    ps, pn = seen[s]
                    path.append(pn)
                    s = ps
                return list(reversed(path)), nodes
            if ns not in seen:
                seen[ns] = (state, name)
                q.append((ns, depth + 1))
    return None, nodes


def render(level, state=None, marks=None):
    pol = state[1] if state else level.start_pol
    ppos = state[0] if state else level.start
    crates = state[2] if state else level.crates
    cmap = {(c[0], c[1]): c[2] for c in crates}
    out = []
    for y in range(level.h):
        line = []
        for x in range(level.w):
            c = (x, y)
            if c == ppos:
                line.append('@' if pol > 0 else '%')
            elif c in cmap:
                line.append('+' if cmap[c] > 0 else '-')
            elif c in level.blocked:
                line.append('#' if c not in level.gate else 'G')
            elif c in level.hazard:
                line.append('H')
            elif c in level.plate:
                line.append('P')
            elif c in level.switch:
                line.append('S')
            elif c in level.gate:
                line.append('G')
            elif c == level.exit:
                line.append('X')
            else:
                line.append('.')
        out.append(''.join(line))
    return '\n'.join(out)


def report(name, rows, hint=""):
    lv = Level(name, rows, hint)
    path, nodes = solve(lv)
    print('=' * 50)
    print(name, '| plates:', len(lv.plate), 'crates:', len(lv.crates), 'hazard:', len(lv.hazard), 'gates:', len(lv.gate))
    print(render(lv))
    if path is None:
        print('!! UNSOLVABLE (nodes %d)' % nodes)
    elif path == 'LIMIT':
        print('!! node limit (nodes %d)' % nodes)
    else:
        print('SOLVED in %d moves (nodes %d): %s' % (len(path), nodes, ' '.join(path)))
    return lv, path


if __name__ == '__main__':
    report('test', [
        '#########',
        '#.......#',
        '#.1+...X#',
        '#.......#',
        '#########',
    ])

