                    return None
                chain.append(nc)
                cur = nxt
                continue
            if self.blocked_cell(nxt, state[2], pw):
                return None
            break
        events['push'] = len(chain)
        for c2 in reversed(chain):
            nxt = (c2[0] + d[0], c2[1] + d[1])
            if nxt in self.hazard:
                destroyed.append(c2)
            else:
                moved.append((c2, nxt))
