    for c2, np in moved:
        del new_crates[(c2[0], c2[1])]
    for c2 in destroyed:
        del new_crates[(c2[0], c2[1])]
    for c2, np in moved:
        new_crates[np] = (np[0], np[1], c2[2])
    # pull: opposite crate directly behind follows the player
    oldp = ppos
    b = (oldp[0] - d[0], oldp[1] - d[1])
    pulled = None
    pull_dest = None
    if b in new_crates:
        c = new_crates[b]
        if c[2] != pol:
            dest = oldp
            del new_crates[b]
            if dest in self.hazard:
                destroyed.append(c)
                events['pull_destroy'] = True
            else:
                new_crates[dest] = (dest[0], dest[1], c[2])
                events['pull'] = True
                pulled = c
                pull_dest = dest
    if destroyed:
        events['destroyed'] = [tuple(c) for c in destroyed]
    # polarity flips: any mover that ends its move on a switch
    flipped = []
    final = []
    for pos, c in new_crates.items():
        pol2 = c[2]
        if pos in self.switch and pos in (np for _, np in moved):
            pol2 = -pol2
            flipped.append(('crate', pos))
        if pulled is not None and pos == pull_dest and pos in self.switch:
            pol2 = -pol2
            flipped.append(('crate', pos))
        final.append((pos[0], pos[1], pol2))
    new_pol = pol
    if t in self.switch:
        new_pol = -pol
        flipped.append(('player', t))
    if flipped:
