extends SceneTree

const LevelsData := preload("res://scripts/levels.gd")
const BoardScript := preload("res://scripts/board.gd")

func _dir(n: String) -> Vector2i:
	match n:
		"up": return Vector2i(0, -1)
		"down": return Vector2i(0, 1)
		"left": return Vector2i(-1, 0)
	return Vector2i(1, 0)

func _initialize() -> void:
	var failures := 0
	for i in LevelsData.count():
		var data: Dictionary = LevelsData.get_level(i)
		var b = BoardScript.new()
		b.load_level(data.rows, i)
		var blocked := 0
		for step in data.solution:
			var ev: Dictionary = b.try_move(_dir(String(step)))
			if not ev.get("ok", false):
				blocked += 1
		var ok: bool = b.won
		if not ok: failures += 1
		print("%-24s won=%s moves=%d/%d plates=%d/%d blocked=%d" % [
			String(data.name), str(ok), b.move_count, data.solution.size(),
			b.plates_loaded(), b.plates_total(), blocked])
	# undo / reset round trip on chamber 8
	var b2 = BoardScript.new()
	b2.load_level(LevelsData.get_level(7).rows, 7)
	for k in 4: b2.try_move(_dir(String(LevelsData.get_level(7).solution[k])))
	var mid := b2.move_count
	var pos_before: Vector2i = b2.player_pos
	b2.try_move(Vector2i(0, 1))
	b2.undo()
	print("undo restores: ", b2.move_count == mid and b2.player_pos == pos_before)
	b2.reset_level()
	print("reset restores: ", b2.move_count == 0 and b2.plates_loaded() == 0)
	print("FAILURES=", failures)
	quit(0)
EOF
